create table streams (
    day_id           timestamp(6),
    genre_id         number(4, 0),
    movie_id         number,
    cust_id          number,
    app              varchar2(100 byte),
    device           varchar2(100 byte),
    os               varchar2(100 byte),
    payment_method   varchar2(100 byte),
    list_price       number(5, 2),
    discount_type    varchar2(100 byte),
    discount_percent number(5, 2),
    sales            number(5, 2),
        views            number(1, 0) generated always as ( 1 ) virtual
);


